class TokenBucket:
    def __init__(self, capacity, refill_per_sec):
        self.capacity = float(capacity)
        self.refill_per_sec = float(refill_per_sec)
        # A bucket starts full.
        self.tokens = float(capacity)
        # Clock of the most recent reading; None until the first call.
        self.last_time = None

    def allow(self, now_ms):
        """True if a request may proceed, consuming one token."""
        if self.last_time is None:
            # The first call establishes the clock and refills nothing.
            self.last_time = now_ms
        else:
            elapsed_ms = now_ms - self.last_time
            if elapsed_ms > 0:
                # Continuous refill: fractional time is never discarded.
                self.tokens += (elapsed_ms / 1000.0) * self.refill_per_sec
                if self.tokens > self.capacity:
                    self.tokens = self.capacity
            # A backwards (or equal) jump grants nothing and is taken as the
            # new clock so the bucket can keep refilling afterwards.
            self.last_time = now_ms

        if self.tokens >= 1:
            self.tokens -= 1
            return True
        return False
